const USER_INFO_KEY = "block_game_user_info";

interface UserInfo {
  uuid: string;
  nickname: string;
}

/**
 * 获取或创建用户信息
 * 首次访问时生成 UUID 和默认昵称
 */
export const getUserInfo = (): UserInfo => {
  try {
    const raw = localStorage.getItem(USER_INFO_KEY);
    if (raw) {
      const info = JSON.parse(raw) as UserInfo;
      // 确保数据结构完整
      if (info.uuid && typeof info.nickname === "string") {
        return info;
      }
    }
  } catch (e) {
    console.error("读取用户信息失败", e);
  }

  // 创建新用户信息
  const newInfo: UserInfo = {
    uuid: generateUUID(),
    nickname: "匿名玩家",
  };

  try {
    localStorage.setItem(USER_INFO_KEY, JSON.stringify(newInfo));
  } catch (e) {
    console.error("保存用户信息失败", e);
  }

  return newInfo;
};

/**
 * 更新用户昵称
 */
export const updateNickname = (nickname: string): UserInfo => {
  const currentInfo = getUserInfo();
  const trimmedNickname = nickname.trim() || "匿名玩家";
  
  const newInfo: UserInfo = {
    uuid: currentInfo.uuid,
    nickname: trimmedNickname,
  };

  try {
    localStorage.setItem(USER_INFO_KEY, JSON.stringify(newInfo));
  } catch (e) {
    console.error("保存用户信息失败", e);
  }

  return newInfo;
};

/**
 * 生成 UUID v4
 */
const generateUUID = (): string => {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  
  // 降级方案：使用随机数生成 UUID
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
};


