const BGM_FILES = [
  "Lullaby.mp3",
  "Menuetto.mp3",
  "土耳其进行曲.mp3",
  "快乐的农夫.mp3",
  "摇篮曲.mp3",
  "路小雨.mp3",
];

export type BgmPlayMode = "loop" | "random";

export type ClearSfxType = "classic" | "pop" | "chime" | "retro";

export const CLEAR_SFX_OPTIONS: { value: ClearSfxType; label: string }[] = [
  { value: "classic", label: "经典" },
  { value: "pop", label: "清脆" },
  { value: "chime", label: "钟声" },
  { value: "retro", label: "复古" },
];

class AudioManager {
  private audioContext: AudioContext | null = null;
  private bgmOscillators: OscillatorNode[] = [];
  private bgmGain: GainNode | null = null;
  private bgmInterval: number | null = null;
  private isPlayingBgm = false;
  private bgmVolume = 0.35;
  private sfxVolume = 0.25;
  private sfxEnabled = true;
  private bgmEnabled = true;
  private bgmFiles: string[] = [];
  private currentBgmIndex = 0;
  private audioElement: HTMLAudioElement | null = null;
  private initialized = false;
  private bgmPlayMode: BgmPlayMode = "loop";
  private clearSfxType: ClearSfxType = "classic";
  private wordPronunciationEnabled = true;
  private wordPronunciationRate = 0.9;
  private wordPronunciationAccent: "us" | "uk" = "us";
  private previousBgmVolume = 0;
  private bgmDuckedForPronunciation = false;
  private pronunciationAudio: HTMLAudioElement | null = null;

  init() {
    if (this.initialized) return;
    this.initialized = true;

    this.sfxEnabled = localStorage.getItem("block_game_sfx") !== "off";
    this.bgmEnabled = localStorage.getItem("block_game_bgm") !== "off";
    this.bgmPlayMode = (localStorage.getItem("block_game_bgm_mode") as BgmPlayMode) || "loop";
    this.clearSfxType = (localStorage.getItem("block_game_clear_sfx") as ClearSfxType) || "classic";
    this.bgmVolume = parseFloat(localStorage.getItem("block_game_bgm_volume") || "0.35");
    this.sfxVolume = parseFloat(localStorage.getItem("block_game_sfx_volume") || "0.25");
    this.wordPronunciationEnabled = localStorage.getItem("block_game_word_pron") !== "off";
    this.wordPronunciationRate = parseFloat(localStorage.getItem("block_game_word_pron_rate") || "0.9");
    this.wordPronunciationAccent = (localStorage.getItem("block_game_word_pron_accent") as "us" | "uk") || "us";

    this.loadAllBgmFiles();

    if (this.bgmEnabled) {
      this.startBgm();
    }

    const tryPlayOnInteraction = () => {
      if (this.bgmEnabled && !this.isPlayingBgm) {
        this.startBgm();
      }
      if (this.isPlayingBgm || !this.bgmEnabled) {
        document.removeEventListener("click", tryPlayOnInteraction);
        document.removeEventListener("touchstart", tryPlayOnInteraction);
        document.removeEventListener("keydown", tryPlayOnInteraction);
      }
    };
    document.addEventListener("click", tryPlayOnInteraction, { once: false });
    document.addEventListener("touchstart", tryPlayOnInteraction, { once: false });
    document.addEventListener("keydown", tryPlayOnInteraction, { once: false });
  }

  setSfxEnabled(on: boolean) {
    this.sfxEnabled = on;
    localStorage.setItem("block_game_sfx", on ? "on" : "off");
  }

  isSfxEnabled() {
    return this.sfxEnabled;
  }

  setBgmEnabled(on: boolean) {
    this.bgmEnabled = on;
    localStorage.setItem("block_game_bgm", on ? "on" : "off");
    if (!on) {
      this.stopBgm();
    } else {
      this.startBgm();
    }
  }

  isBgmEnabled() {
    return this.bgmEnabled;
  }

  loadBgmFiles(files: string[]) {
    this.bgmFiles = files;
    const savedIndex = localStorage.getItem("block_game_bgm_index");
    this.currentBgmIndex = savedIndex ? parseInt(savedIndex) : 0;
  }

  loadAllBgmFiles() {
    this.bgmFiles = [...BGM_FILES];
    const savedIndex = localStorage.getItem("block_game_bgm_index");
    this.currentBgmIndex = savedIndex ? parseInt(savedIndex) : 0;
  }

  changeBgm(index: number) {
    if (index < 0 || index >= this.bgmFiles.length) return;
    this.currentBgmIndex = index;
    localStorage.setItem("block_game_bgm_index", String(index));
    if (this.bgmEnabled && this.isPlayingBgm) {
      this.stopBgm();
      this.startBgm();
    }
  }

  getCurrentBgmIndex() {
    return this.currentBgmIndex;
  }

  getBgmFiles() {
    return [...this.bgmFiles];
  }

  setBgmPlayMode(mode: BgmPlayMode) {
    this.bgmPlayMode = mode;
    localStorage.setItem("block_game_bgm_mode", mode);
    if (this.audioElement) {
      this.audioElement.loop = mode === "loop";
    }
  }

  getBgmPlayMode(): BgmPlayMode {
    return this.bgmPlayMode;
  }

  setClearSfxType(type: ClearSfxType) {
    this.clearSfxType = type;
    localStorage.setItem("block_game_clear_sfx", type);
  }

  getClearSfxType(): ClearSfxType {
    return this.clearSfxType;
  }

  private playNextRandomBgm() {
    if (this.bgmFiles.length <= 1) return;
    let nextIndex;
    do {
      nextIndex = Math.floor(Math.random() * this.bgmFiles.length);
    } while (nextIndex === this.currentBgmIndex && this.bgmFiles.length > 1);
    this.currentBgmIndex = nextIndex;
    localStorage.setItem("block_game_bgm_index", String(nextIndex));
  }

  private ensureContext() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as typeof window & { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
    }
    if (this.audioContext.state === "suspended") {
      this.audioContext.resume();
    }
    return this.audioContext;
  }

  playClearSfx() {
    if (!this.sfxEnabled) return;
    const ctx = this.ensureContext();
    const now = ctx.currentTime;

    if (this.clearSfxType === "classic") {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(200, now + 0.18);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(this.sfxVolume, now + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.2);

      const noise = ctx.createOscillator();
      const noiseGain = ctx.createGain();
      noise.type = "square";
      noise.frequency.setValueAtTime(400, now);
      noise.frequency.exponentialRampToValueAtTime(80, now + 0.1);
      noiseGain.gain.setValueAtTime(0, now);
      noiseGain.gain.linearRampToValueAtTime(this.sfxVolume * 0.3, now + 0.01);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
      noise.connect(noiseGain).connect(ctx.destination);
      noise.start(now);
      noise.stop(now + 0.12);
    } else if (this.clearSfxType === "pop") {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(1600, now + 0.06);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.15);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(this.sfxVolume * 1.2, now + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.18);
    } else if (this.clearSfxType === "chime") {
      const freqs = [1318, 1568, 2093];
      freqs.forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const t = now + i * 0.04;
        osc.type = "sine";
        osc.frequency.setValueAtTime(freq, t);
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(this.sfxVolume * 0.8, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
        osc.connect(gain).connect(ctx.destination);
        osc.start(t);
        osc.stop(t + 0.5);
      });
    } else if (this.clearSfxType === "retro") {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "square";
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(880, now + 0.05);
      osc.frequency.setValueAtTime(660, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(this.sfxVolume * 0.6, now + 0.005);
      gain.gain.setValueAtTime(this.sfxVolume * 0.6, now + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.15);
    }
  }

  playMoveSfx() {
    if (!this.sfxEnabled) return;
    const ctx = this.ensureContext();
    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(440, now);
    osc.frequency.exponentialRampToValueAtTime(550, now + 0.08);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(this.sfxVolume * 0.3, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.12);
  }

  playWinSfx() {
    if (!this.sfxEnabled) return;
    const ctx = this.ensureContext();
    const notes = [523, 659, 784, 1047];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const t = ctx.currentTime + i * 0.15;
      osc.type = "triangle";
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(this.sfxVolume * 0.5, t + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
      osc.connect(gain).connect(ctx.destination);
      osc.start(t);
      osc.stop(t + 0.4);
    });
  }

  playFailSfx() {
    if (!this.sfxEnabled) return;
    const ctx = this.ensureContext();
    const notes = [392, 349, 311, 262];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const t = ctx.currentTime + i * 0.18;
      osc.type = "sawtooth";
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(this.sfxVolume * 0.3, t + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
      osc.connect(gain).connect(ctx.destination);
      osc.start(t);
      osc.stop(t + 0.35);
    });
  }

  startBgm() {
    if (this.isPlayingBgm || !this.bgmEnabled) return;
    
    // 如果有 MP3 文件，使用 MP3 播放
    if (this.bgmFiles.length > 0) {
      this.isPlayingBgm = true;
      this.audioElement = new Audio(`${import.meta.env.BASE_URL}audio/${this.bgmFiles[this.currentBgmIndex]}`);
      this.audioElement.loop = this.bgmPlayMode === "loop";
      this.audioElement.volume = this.bgmVolume;
      
      if (this.bgmPlayMode === "random") {
        this.audioElement.addEventListener("ended", () => {
          if (!this.isPlayingBgm) return;
          this.stopBgm();
          this.playNextRandomBgm();
          this.startBgm();
        });
      }
      
      this.audioElement.play().catch((e) => {
        console.error("播放背景音乐失败:", e);
        this.isPlayingBgm = false;
      });
      return;
    }
    
    // 否则使用合成音乐
    const ctx = this.ensureContext();
    this.isPlayingBgm = true;

    this.bgmGain = ctx.createGain();
    this.bgmGain.gain.setValueAtTime(this.bgmVolume, ctx.currentTime);
    this.bgmGain.connect(ctx.destination);

    const melody = [
      523, 587, 659, 698, 784, 698, 659, 587,
      523, 587, 659, 784, 880, 784, 659, 587,
      523, 659, 784, 880, 784, 659, 587, 523,
      587, 659, 784, 659, 587, 523, 494, 523,
    ];

    const bassNotes = [131, 131, 165, 165, 196, 196, 165, 131];

    let noteIndex = 0;
    let bassIndex = 0;
    const noteDuration = 0.35;

    const playNote = () => {
      if (!this.isPlayingBgm || !this.bgmGain) return;

      const freq = melody[noteIndex % melody.length];
      const now = ctx.currentTime;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(freq, now);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.35, now + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, now + noteDuration * 0.9);
      osc.connect(gain).connect(this.bgmGain);
      osc.start(now);
      osc.stop(now + noteDuration);

      if (noteIndex % 4 === 0) {
        const bassFreq = bassNotes[bassIndex % bassNotes.length];
        const bassOsc = ctx.createOscillator();
        const bassGain = ctx.createGain();
        bassOsc.type = "sine";
        bassOsc.frequency.setValueAtTime(bassFreq, now);
        bassGain.gain.setValueAtTime(0, now);
        bassGain.gain.linearRampToValueAtTime(0.5, now + 0.05);
        bassGain.gain.exponentialRampToValueAtTime(0.001, now + noteDuration * 3.5);
        bassOsc.connect(bassGain).connect(this.bgmGain);
        bassOsc.start(now);
        bassOsc.stop(now + noteDuration * 3.5);
        bassIndex++;
      }

      noteIndex++;
    };

    playNote();
    this.bgmInterval = window.setInterval(playNote, noteDuration * 1000);
  }

  stopBgm() {
    this.isPlayingBgm = false;
    
    // 停止 MP3 播放
    if (this.audioElement) {
      this.audioElement.pause();
      this.audioElement = null;
    }
    
    // 停止合成音乐
    if (this.bgmInterval !== null) {
      clearInterval(this.bgmInterval);
      this.bgmInterval = null;
    }
    if (this.bgmGain) {
      try {
        this.bgmGain.gain.exponentialRampToValueAtTime(0.001, this.audioContext!.currentTime + 0.3);
        setTimeout(() => {
          this.bgmGain?.disconnect();
          this.bgmGain = null;
        }, 350);
      } catch {
        this.bgmGain.disconnect();
        this.bgmGain = null;
      }
    }
  }

  setBgmVolume(v: number) {
    this.bgmVolume = v;
    localStorage.setItem("block_game_bgm_volume", String(v));
    if (this.bgmGain) {
      this.bgmGain.gain.setValueAtTime(v, this.audioContext!.currentTime);
    }
    if (this.audioElement) {
      this.audioElement.volume = v;
    }
  }

  getBgmVolume() {
    return this.bgmVolume;
  }

  setSfxVolume(v: number) {
    this.sfxVolume = v;
    localStorage.setItem("block_game_sfx_volume", String(v));
  }

  getSfxVolume() {
    return this.sfxVolume;
  }

  getBgmPlaying() {
    return this.isPlayingBgm;
  }

  setWordPronunciationEnabled(on: boolean) {
    this.wordPronunciationEnabled = on;
    localStorage.setItem("block_game_word_pron", on ? "on" : "off");
    if (!on) {
      this.stopWordPronunciation();
    }
  }

  isWordPronunciationEnabled() {
    return this.wordPronunciationEnabled;
  }

  setWordPronunciationRate(rate: number) {
    this.wordPronunciationRate = rate;
    localStorage.setItem("block_game_word_pron_rate", String(rate));
  }

  getWordPronunciationRate() {
    return this.wordPronunciationRate;
  }

  setWordPronunciationAccent(accent: "us" | "uk") {
    this.wordPronunciationAccent = accent;
    localStorage.setItem("block_game_word_pron_accent", accent);
  }

  getWordPronunciationAccent() {
    return this.wordPronunciationAccent;
  }

  private duckBgm() {
    if (this.bgmEnabled && this.isPlayingBgm && !this.bgmDuckedForPronunciation) {
      this.previousBgmVolume = this.bgmVolume;
      const duckedVolume = Math.max(0.03, this.bgmVolume * 0.25);
      if (this.bgmGain && this.audioContext) {
        this.bgmGain.gain.setValueAtTime(duckedVolume, this.audioContext.currentTime);
      }
      if (this.audioElement) {
        this.audioElement.volume = duckedVolume;
      }
      this.bgmDuckedForPronunciation = true;
    }
  }

  private restoreBgm() {
    if (this.bgmDuckedForPronunciation) {
      if (this.bgmGain && this.audioContext) {
        this.bgmGain.gain.setValueAtTime(this.previousBgmVolume, this.audioContext.currentTime);
      }
      if (this.audioElement) {
        this.audioElement.volume = this.previousBgmVolume;
      }
      this.bgmDuckedForPronunciation = false;
    }
  }

  speakWord(word: string) {
    if (!this.wordPronunciationEnabled) return;
    if (!word || !word.trim()) return;
    if (typeof window === "undefined") return;

    const trimmed = word.trim();

    if (this.pronunciationAudio) {
      this.pronunciationAudio.pause();
      this.pronunciationAudio = null;
    }

    this.bgmDuckedForPronunciation = false;
    this.duckBgm();

    let restored = false;
    const doRestore = () => {
      if (!restored) {
        restored = true;
        this.restoreBgm();
      }
    };

    const audio = new Audio();
    this.pronunciationAudio = audio;
    audio.preload = "auto";

    audio.onplay = () => {
      this.duckBgm();
    };
    audio.onended = () => {
      doRestore();
      this.pronunciationAudio = null;
    };
    audio.onerror = () => {
      doRestore();
      this.pronunciationAudio = null;
    };

    const type = this.wordPronunciationAccent === "uk" ? 1 : 0;
    const src = `https://dict.youdao.com/dictvoice?type=${type}&audio=${encodeURIComponent(trimmed)}`;
    audio.src = src;
    audio.playbackRate = this.wordPronunciationRate;

    audio.play().catch(() => {
      doRestore();
      this.pronunciationAudio = null;
    });
  }

  stopWordPronunciation() {
    if (this.pronunciationAudio) {
      this.pronunciationAudio.pause();
      this.pronunciationAudio = null;
    }
    this.restoreBgm();
  }
}

export const audioManager = new AudioManager();
