import { RotateCcw, Undo2, Lightbulb, Coins, ShoppingBag, X, RefreshCw, ArrowLeftRight, XCircle, Shuffle } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { ItemType } from "@/types/game";

interface ShopModalProps {
  open: boolean;
  onClose: () => void;
}

const ITEM_INFO: Record<ItemType, { name: string; icon: React.ReactNode; color: string }> = {
  restart: {
    name: "重来",
    icon: <RotateCcw size={28} className="text-rose-100" />,
    color: "from-rose-600/80 to-red-700/80",
  },
  undo: {
    name: "撤销",
    icon: <Undo2 size={28} className="text-blue-100" />,
    color: "from-blue-600/80 to-indigo-700/80",
  },
  hint: {
    name: "提示",
    icon: <Lightbulb size={28} className="text-amber-100" />,
    color: "from-amber-600/80 to-orange-700/80",
  },
  swap: {
    name: "置换",
    icon: <ArrowLeftRight size={28} className="text-violet-100" />,
    color: "from-violet-600/80 to-purple-700/80",
  },
  clearType: {
    name: "消除",
    icon: <XCircle size={28} className="text-red-100" />,
    color: "from-red-600/80 to-rose-700/80",
  },
  shuffle: {
    name: "洗牌",
    icon: <Shuffle size={28} className="text-emerald-100" />,
    color: "from-emerald-600/80 to-green-700/80",
  },
};

export default function ShopModal({ open, onClose }: ShopModalProps) {
  const coins = useGameStore((s) => s.coins);
  const shopItems = useGameStore((s) => s.shopItems);
  const buyShopItem = useGameStore((s) => s.buyShopItem);
  const refreshShop = useGameStore((s) => s.refreshShop);
  const shopRefreshCount = useGameStore((s) => s.shopRefreshCount);

  const refreshPrice = shopRefreshCount + 1;
  const canRefresh = shopRefreshCount < 3 && coins >= refreshPrice;
  const refreshLeft = 3 - shopRefreshCount;

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-amber-500/30 rounded-3xl p-6 sm:p-8 max-w-md w-full shadow-2xl">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/50">
            <ShoppingBag className="text-white" size={24} />
          </div>
        </div>

        <button
          onClick={onClose}
          className="absolute top-4 right-4 w-8 h-8 rounded-full bg-slate-700/50 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-600/50 transition-all"
        >
          <X size={18} />
        </button>

        <h2 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-400 via-orange-400 to-yellow-400 mb-2 mt-4 text-center">
          道具商店
        </h2>

        <div className="flex items-center justify-center gap-2 mb-6 bg-amber-500/20 rounded-full px-4 py-2 mx-auto w-fit border border-amber-400/30">
          <Coins size={18} className="text-amber-400" />
          <span className="text-amber-300 font-bold">{coins}</span>
        </div>

        <div className="grid grid-cols-4 gap-2 mb-4">
          {shopItems.length === 0 ? (
            <div className="col-span-4 text-center text-slate-500 py-8">
              商品已售罄，请刷新
            </div>
          ) : (
            shopItems.map((item) => {
              const info = ITEM_INFO[item.type];
              const canBuy = coins >= item.price;
              return (
                <div key={item.id} className="flex flex-col items-center">
                  <div
                    className={`w-14 h-14 sm:w-16 sm:h-16 rounded-xl bg-gradient-to-br ${info.color} border-2 border-white/20 flex items-center justify-center shadow-lg mb-2`}
                  >
                    {info.icon}
                  </div>
                  <span className="text-slate-300 text-xs mb-1">{info.name}</span>
                  <button
                    onClick={() => buyShopItem(item.id)}
                    disabled={!canBuy}
                    className={`flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold transition-all ${
                      canBuy
                        ? "bg-gradient-to-r from-amber-500 to-orange-500 text-white hover:from-amber-400 hover:to-orange-400 hover:scale-105 active:scale-95"
                        : "bg-slate-700 text-slate-500 cursor-not-allowed"
                    }`}
                  >
                    <Coins size={12} />
                    {item.price}
                  </button>
                </div>
              );
            })
          )}
        </div>

        <button
          onClick={refreshShop}
          disabled={!canRefresh}
          className={`w-full flex items-center justify-center gap-2 py-3 rounded-xl transition-all border ${
            canRefresh
              ? "bg-gradient-to-r from-amber-500/20 to-orange-500/20 hover:from-amber-500/30 hover:to-orange-500/30 text-amber-300 border-amber-400/50 hover:scale-105 active:scale-95"
              : "bg-slate-700/50 text-slate-500 border-slate-600/50 cursor-not-allowed"
          }`}
        >
          <RefreshCw size={16} />
          <span>{shopRefreshCount >= 3 ? "刷新次数已用完" : "刷新商品"}</span>
          {shopRefreshCount < 3 && (
            <>
              <div className="flex items-center gap-1 ml-1">
                <Coins size={14} className={canRefresh ? "text-amber-400" : "text-slate-600"} />
                <span className={`font-bold ${canRefresh ? "text-amber-400" : "text-slate-600"}`}>{refreshPrice}</span>
              </div>
              <span className={`text-xs ${canRefresh ? "text-amber-400/70" : "text-slate-600"}`}>
                (剩 {refreshLeft} 次)
              </span>
            </>
          )}
        </button>
      </div>
    </div>
  );
}
