export type PkRoomStatus = "waiting" | "ready" | "playing" | "finished";
export type PkMatchMode = "same" | "different";

export interface PkRoom {
  id: string;
  hostUuid: string;
  hostNickname: string;
  guestUuid: string | null;
  guestNickname: string | null;
  status: PkRoomStatus;
  questionCount: number;
  timePerQuestion: number;
  matchMode: PkMatchMode;
  importRecordId: string | null;
  importRecordTitle: string | null;
  sourceType: "import" | "random";
  questionWords: Array<{ spelling: string; meaning: string }>;
  guestImportRecordId: string | null;
  guestImportRecordTitle: string | null;
  guestSourceType: "import" | "random" | null;
  guestQuestionWords: Array<{ spelling: string; meaning: string }> | null;
  spellingRatio: number;
  hostReady: boolean;
  guestReady: boolean;
  currentQuestion: number;
  createdAt: number;
  updatedAt: number;
}

export type PkQuestionType = "choice" | "spelling";

export interface PkQuestion {
  type: PkQuestionType;
  word: string;
  meaning: string;
  correctOption: string;
  options?: string[];
  shuffledLetters?: string[];
}

export interface PkAnswer {
  roomId: string;
  questionIndex: number;
  questionWord: string;
  correctAnswer: string;
  options: string[];
  hostQuestionWord: string;
  hostCorrectAnswer: string;
  guestQuestionWord: string;
  guestCorrectAnswer: string;
  hostAnswer: string | null;
  hostTime: number | null;
  hostScore: number | null;
  guestAnswer: string | null;
  guestTime: number | null;
  guestScore: number | null;
}

export interface PkResult {
  roomId: string;
  winnerUuid: string | null;
  winnerNickname: string | null;
  hostTotal: number;
  guestTotal: number;
  hostCorrect: number;
  guestCorrect: number;
  finishedAt: number;
}

export interface ImportRecord {
  id: string;
  ownerUuid: string;
  ownerNickname: string;
  title: string;
  wordCount: number;
  words: Array<{ spelling: string; meaning: string }>;
  isPublic: boolean;
  createdAt: number;
}

export function generateRoomCode(): string {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < 6; i++) {
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return code;
}
