import { Sprout, ShoppingBag, Package, Coins, ChevronRight, Brain, Truck } from "lucide-react";
import { SeedType, GrowthStage, SEED_CONFIGS, PLOT_UNLOCK_COSTS } from "@/types/game";
import type { useFarmUI, TabType } from "@/hooks/useFarmUI";
import { useFarmStore } from "@/store/useFarmStore";

type FarmUIState = ReturnType<typeof useFarmUI>;

const STAGE_CONFIG: Record<GrowthStage, { label: string; icon: string }> = {
  seedling: { label: "幼苗", icon: "🌱" },
  flowering: { label: "开花", icon: "🌸" },
  fruiting: { label: "结果", icon: "🍎" },
};

const TABS: { key: TabType; label: string; icon: typeof Sprout }[] = [
  { key: "field", label: "种植区", icon: Sprout },
  { key: "shop", label: "种子店", icon: ShoppingBag },
  { key: "warehouse", label: "仓库", icon: Package },
];

function PlotButton({ index, ui }: { index: number; ui: FarmUIState }) {
  const {
    selectedSeed, openedPlots, sunlight, selectedPlot,
    getCropAtPlot, getGrowthStage, getStageProgress,
    getTimeRemaining, isReadyToHarvest,
    handleUnlockPlot, handlePlotClick,
    debugAdvanceCrop, debugRipenCrop, setTick, showMsg,
  } = ui;

  const crop = getCropAtPlot(index);
  const stolenRecords = useFarmStore((s) => s.stolenRecords);
  const stolen = !crop && stolenRecords.find((r) => r.plotIndex === index);
  const isLocked = index >= openedPlots;
  const canPlant = !crop && !isLocked && selectedSeed && !stolen;
  const isSelected = selectedPlot === index && crop && !isReadyToHarvest(crop);

  if (isLocked) {
    const cost = PLOT_UNLOCK_COSTS[index];
    const canUnlock = sunlight >= cost;
    const isNext = index === openedPlots;
    return (
      <button
        key={index}
        onClick={isNext ? handleUnlockPlot : undefined}
        disabled={!isNext}
        className={`aspect-square rounded-2xl border-2 flex flex-col items-center justify-center gap-1 transition-all ${
          isNext
            ? canUnlock
              ? "bg-slate-800/30 border-amber-500/50 hover:bg-amber-500/10 hover:scale-105 cursor-pointer"
              : "bg-slate-800/30 border-slate-600/50 cursor-pointer"
            : "bg-slate-900/50 border-slate-700/30 opacity-40"
        }`}
      >
        <span className="text-2xl opacity-60">🔒</span>
        {isNext && (
          <span className="text-[10px] text-amber-400 font-medium">☀️ {cost} 开垦</span>
        )}
      </button>
    );
  }

  if (crop) {
    const stage = getGrowthStage(crop);
    const progress = getStageProgress(crop);
    const ready = isReadyToHarvest(crop);
    const config = SEED_CONFIGS[crop.seedType];
    const remaining = getTimeRemaining(crop);
    // 是否已熟透（成熟超过1小时，可以被偷）
    const elapsedMs = Date.now() - crop.plantedAt;
    const totalMs = config.growthHours * 3600000;
    const stealable = ready && (elapsedMs - totalMs >= 3600000);

    return (
      <div key={index} className="relative">
        <button
          onClick={() => handlePlotClick(index)}
          className={`relative w-full aspect-square rounded-2xl border-2 flex flex-col items-center justify-center gap-1 transition-all ${
            isSelected
              ? "bg-sky-500/20 border-sky-400/60 ring-2 ring-sky-400/40 scale-105"
              : ready
              ? "bg-emerald-500/20 border-emerald-400/50 hover:bg-emerald-500/30 hover:scale-105"
              : "bg-amber-900/30 border-amber-600/30 hover:border-amber-500/50"
          }`}
        >
          <span className="text-3xl">{ready ? config.fruitEmoji : STAGE_CONFIG[stage].icon}</span>
          <span className="text-[10px] text-slate-300">{config.name}</span>
          <div className="absolute bottom-1.5 left-1.5 right-1.5">
            <div className="w-full h-1 bg-slate-700/50 rounded-full overflow-hidden">
              <div
                className={`h-full transition-all ${ready ? "bg-emerald-400" : "bg-amber-400"}`}
                style={{ width: `${Math.round(progress * 100)}%` }}
              />
            </div>
          </div>
          {ready && (
            <div className="absolute -top-1 -right-1 w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold border border-emerald-300">✓</div>
          )}
          {!ready && (
            <span className="absolute top-1 right-1 text-[9px] text-slate-400 bg-slate-800/70 rounded px-1">
              {remaining.hours > 0 ? `${remaining.hours}h${remaining.minutes}m` : `${remaining.minutes}m`}
            </span>
          )}
        </button>
        {import.meta.env.DEV && !ready && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              debugAdvanceCrop(crop.id, 4);
              setTick((t) => t + 1);
              showMsg(`已跳过 4 小时（下阶段）`, "success");
            }}
            className="absolute -bottom-4 left-1/2 -translate-x-1/2 whitespace-nowrap px-2 py-0.5 bg-indigo-600/70 hover:bg-indigo-500/70 text-white text-[9px] rounded-full border border-indigo-400/40 transition-all hover:scale-105 active:scale-95 z-10"
          >
            +4h 跳过
          </button>
        )}
        {import.meta.env.DEV && ready && (
          <button
            onClick={async (e) => {
              e.stopPropagation();
              if (stealable) {
                showMsg(`已经是熟透状态了`, "success");
                return;
              }
              showMsg(`正在熟透并同步到 GitHub...`, "success");
              await debugRipenCrop(crop.id);
              setTick((t) => t + 1);
              showMsg(`已熟透（可被偷），已同步`, "success");
            }}
            className="absolute -top-1 -left-1 whitespace-nowrap px-1.5 py-0.5 bg-rose-600/80 hover:bg-rose-500/80 text-white text-[9px] rounded-full border border-rose-400/40 transition-all hover:scale-105 active:scale-95 z-10"
          >
            {stealable ? "已熟透" : "熟透"}
          </button>
        )}
      </div>
    );
  }

  // 被偷了的地块
  if (stolen) {
    const cfg = SEED_CONFIGS[stolen.seedType as SeedType];
    return (
      <button
        key={index}
        onClick={() => handlePlotClick(index)}
        className="aspect-square rounded-2xl border-2 border-dashed border-slate-600/40 bg-slate-800/30 flex flex-col items-center justify-center opacity-80 hover:opacity-100"
      >
        <span className="text-3xl grayscale opacity-50">🥀</span>
        <span className="text-[9px] text-slate-500">{cfg?.name || "作物"}被偷</span>
      </button>
    );
  }

  return (
    <button
      key={index}
      onClick={() => handlePlotClick(index)}
      className={`aspect-square rounded-2xl border-2 border-dashed flex flex-col items-center justify-center transition-all ${
        canPlant
          ? "bg-emerald-500/10 border-emerald-400/50 hover:bg-emerald-500/20 hover:scale-105"
          : "bg-slate-800/20 border-slate-600/30"
      }`}
    >
      <span className="text-2xl opacity-40">➕</span>
      <span className="text-[10px] text-slate-500">{canPlant ? "点击种植" : "空地"}</span>
    </button>
  );
}

function SeedInventory({ ui }: { ui: FarmUIState }) {
  const { seedInventory, unlockedSeeds, selectedSeed, setSelectedSeed } = ui;
  return (
    <div>
      <p className="text-slate-400 text-xs mb-2">选择种子后点击空地种植</p>
      <div className="grid grid-cols-6 gap-1">
        {(Object.keys(SEED_CONFIGS) as SeedType[]).map((seedType) => {
          const config = SEED_CONFIGS[seedType];
          const count = seedInventory[seedType] || 0;
          const isUnlocked = unlockedSeeds.includes(seedType);
          const isSelected = selectedSeed === seedType;
          return (
            <button
              key={seedType}
              onClick={() => count > 0 && setSelectedSeed(isSelected ? null : seedType)}
              disabled={count === 0 || !isUnlocked}
              className={`flex flex-col items-center gap-0.5 p-1.5 rounded-lg border-2 transition-all ${
                isSelected
                  ? "bg-emerald-500/30 border-cyan-400 shadow-lg shadow-cyan-500/20"
                  : count > 0 && isUnlocked
                  ? "bg-slate-800/50 border-slate-600/30 hover:border-emerald-500/30"
                  : "bg-slate-800/20 border-slate-700/20 opacity-40 cursor-not-allowed"
              }`}
            >
              <span className="text-base">{isUnlocked ? config.emoji : "🔒"}</span>
              <span className="text-[8px] text-slate-400">{isUnlocked ? `×${count}` : "未解锁"}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function FieldArea({ ui, gridWidth = "max-w-[280px]" }: { ui: FarmUIState; gridWidth?: string }) {
  const { selectedSeed, openedPlots, totalPlots } = ui;
  return (
    <div>
      <p className="text-slate-400 text-xs mb-2">
        种植区 ({openedPlots}/{totalPlots} 已开垦)
        {selectedSeed && (
          <span className="text-emerald-400 ml-2">
            已选：{SEED_CONFIGS[selectedSeed].emoji} {SEED_CONFIGS[selectedSeed].name}
          </span>
        )}
      </p>
      <div className={`grid grid-cols-3 gap-1.5 ${gridWidth} mx-auto`}>
        {Array.from({ length: totalPlots }).map((_, i) => (
          <PlotButton key={i} index={i} ui={ui} />
        ))}
      </div>
    </div>
  );
}

function ToolBar({ ui }: { ui: FarmUIState }) {
  const { selectedPlot, getCropAtPlot, isReadyToHarvest, handleWater, handleWeed, handleFertilize, sunlight } = ui;
  const crop = selectedPlot !== null ? getCropAtPlot(selectedPlot) : undefined;

  if (selectedPlot === null || !crop) {
    return (
      <div className="bg-slate-800/30 rounded-xl p-3 border border-slate-700/30">
        <p className="text-slate-500 text-xs text-center">点击未成熟的作物，使用工具加速生长</p>
      </div>
    );
  }

  if (isReadyToHarvest(crop)) {
    return (
      <div className="bg-emerald-500/10 rounded-xl p-3 border border-emerald-500/30">
        <p className="text-emerald-400 text-xs text-center">✓ 作物已成熟，点击即可收获</p>
      </div>
    );
  }

  const config = SEED_CONFIGS[crop.seedType];
  return (
    <div className="bg-slate-800/50 rounded-xl p-3 border border-slate-700/40">
      <div className="flex items-center gap-2 mb-3">
        <span className="text-xl">{config.fruitEmoji}</span>
        <span className="text-slate-300 text-sm font-medium">{config.name}</span>
      </div>
      <div className="grid grid-cols-3 gap-2">
        <button
          onClick={handleWater}
          disabled={sunlight < 2}
          className="flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all bg-sky-500/10 border-sky-500/30 hover:bg-sky-500/20 disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <span className="text-xl">💧</span>
          <span className="text-sky-300 text-[11px] font-medium">浇水</span>
          <span className="text-sky-400/70 text-[9px]">-1h · 2☀️</span>
        </button>
        <button
          onClick={handleWeed}
          disabled={sunlight < 5}
          className="flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all bg-emerald-500/10 border-emerald-500/30 hover:bg-emerald-500/20 disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <span className="text-xl">🌿</span>
          <span className="text-emerald-300 text-[11px] font-medium">除草</span>
          <span className="text-emerald-400/70 text-[9px]">-3h · 5☀️</span>
        </button>
        <button
          onClick={handleFertilize}
          disabled={sunlight < 10}
          className="flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all bg-violet-500/10 border-violet-500/30 hover:bg-violet-500/20 disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <span className="text-xl">✨</span>
          <span className="text-violet-300 text-[11px] font-medium">施肥</span>
          <span className="text-violet-400/70 text-[9px]">-8h · 10☀️</span>
        </button>
      </div>
    </div>
  );
}

function ShopList({ ui }: { ui: FarmUIState }) {
  const { unlockedSeeds, sunlight, handleBuy, handleUnlockSeed } = ui;
  return (
    <div className="space-y-2 pb-4">
      <p className="text-slate-400 text-xs">使用答题获得的阳光☀️解锁并购买种子</p>
      {(Object.keys(SEED_CONFIGS) as SeedType[])
        .sort((a, b) => SEED_CONFIGS[a].unlockCost - SEED_CONFIGS[b].unlockCost)
        .map((seedType) => {
          const config = SEED_CONFIGS[seedType];
          const isUnlocked = unlockedSeeds.includes(seedType);
          const canUnlock = !isUnlocked && sunlight >= config.unlockCost;
          const canBuy = isUnlocked && sunlight >= config.sunlightPrice;
          return (
            <div
              key={seedType}
              className={`flex items-center gap-3 p-3 rounded-xl border ${
                isUnlocked
                  ? "bg-slate-800/50 border-slate-700/30"
                  : "bg-slate-900/50 border-slate-700/20"
              }`}
            >
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${
                isUnlocked
                  ? "bg-gradient-to-br from-emerald-500/30 to-teal-500/30"
                  : "bg-slate-800/50 opacity-50"
              }`}>
                <span className="text-2xl">{config.emoji}</span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-slate-200 font-semibold text-sm flex items-center gap-1.5">
                  {config.name}种子
                  {!isUnlocked && <span className="text-[9px] text-slate-500">未解锁</span>}
                </p>
                <p className="text-slate-500 text-[11px]">
                  {isUnlocked
                    ? `${config.growthHours}h成熟 · 果实值 ${config.fruitCoins} 积分`
                    : `解锁后可购买 · ${config.growthHours}h成熟 · 果实值 ${config.fruitCoins} 积分`}
                </p>
              </div>
              {isUnlocked ? (
                <button
                  onClick={() => handleBuy(seedType)}
                  disabled={!canBuy}
                  className={`shrink-0 px-3 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-1 ${
                    canBuy
                      ? "bg-gradient-to-r from-yellow-500 to-amber-500 hover:from-yellow-400 hover:to-amber-400 text-white shadow-lg shadow-yellow-500/20"
                      : "bg-slate-700/50 text-slate-500 cursor-not-allowed"
                  }`}
                >
                  <span>☀️</span>{config.sunlightPrice}
                </button>
              ) : (
                <button
                  onClick={() => handleUnlockSeed(seedType)}
                  disabled={!canUnlock}
                  className={`shrink-0 px-3 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-1 ${
                    canUnlock
                      ? "bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 text-white shadow-lg shadow-violet-500/20"
                      : "bg-slate-700/50 text-slate-500 cursor-not-allowed"
                  }`}
                >
                  🔒 ☀️{config.unlockCost}
                </button>
              )}
            </div>
          );
        })}
    </div>
  );
}

function WarehouseList({ ui, showDeliveryEntry }: { ui: FarmUIState; showDeliveryEntry?: boolean }) {
  const {
    warehouse, sellAmounts, totalWarehouseValue,
    handleSellAll, handleSell, adjustSellAmount,
  } = ui;

  return (
    <div className="space-y-3 pb-4">
      {showDeliveryEntry && (
        <button
          onClick={() => { window.location.hash = "#/delivery"; }}
          className="w-full py-3 px-4 bg-gradient-to-r from-amber-500/20 to-orange-500/20 hover:from-amber-500/30 hover:to-orange-500/30 border border-amber-500/40 rounded-xl transition-all flex items-center justify-between"
        >
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-500 to-orange-500 flex items-center justify-center">
              <Truck className="text-white" size={20} />
            </div>
            <div className="text-left">
              <p className="text-amber-200 font-bold text-sm">鲜果速递</p>
              <p className="text-amber-400/70 text-[11px]">接单送货，赚取更多阳光☀️</p>
            </div>
          </div>
          <ChevronRight className="text-amber-400" size={20} />
        </button>
      )}

      <div className="flex items-center justify-between">
        <p className="text-slate-400 text-xs">仓库中的果实可兑换积分</p>
        <button
          onClick={handleSellAll}
          disabled={totalWarehouseValue === 0}
          className="text-xs px-3 py-1.5 rounded-lg bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-medium transition-all flex items-center gap-1"
        >
          全部卖出 <ChevronRight size={12} />
        </button>
      </div>

      {totalWarehouseValue > 0 && (
        <div className="bg-amber-500/10 rounded-xl px-4 py-3 border border-amber-400/30 text-center">
          <p className="text-amber-300/70 text-xs">预计总价值</p>
          <p className="text-amber-300 font-bold text-xl">
            <Coins size={18} className="inline mr-1" />{totalWarehouseValue}
          </p>
        </div>
      )}

      <div className="space-y-2">
        {(Object.keys(warehouse) as SeedType[])
          .filter((s) => (warehouse[s] || 0) > 0)
          .sort((a, b) => SEED_CONFIGS[a].fruitCoins - SEED_CONFIGS[b].fruitCoins)
          .map((seedType) => {
          const count = warehouse[seedType] || 0;
          const config = SEED_CONFIGS[seedType];
          const sellAmount = Math.min(sellAmounts[seedType] || 1, count);
          const sellValue = sellAmount * config.fruitCoins;
          return (
            <div
              key={seedType}
              className="flex items-center gap-3 p-3 rounded-xl bg-slate-800/50 border border-slate-700/30"
            >
              <div className="w-10 h-10 rounded-xl bg-slate-700/50 flex items-center justify-center shrink-0">
                <span className="text-xl">{config.fruitEmoji}</span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-slate-200 font-semibold text-sm">{config.name}</p>
                <p className="text-slate-500 text-[11px]">库存 ×{count} · 单个 {config.fruitCoins} 积分</p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <div className="flex items-center gap-1 bg-slate-700/50 rounded-lg p-0.5">
                  <button
                    onClick={() => adjustSellAmount(seedType, -1)}
                    className="w-6 h-6 rounded-md bg-slate-600/50 hover:bg-slate-500/50 text-slate-300 font-bold text-sm transition-all active:scale-90"
                  >−</button>
                  <span className="text-slate-200 font-bold text-sm w-7 text-center">{sellAmount}</span>
                  <button
                    onClick={() => adjustSellAmount(seedType, 1)}
                    className="w-6 h-6 rounded-md bg-slate-600/50 hover:bg-slate-500/50 text-slate-300 font-bold text-sm transition-all active:scale-90"
                  >+</button>
                </div>
                <button
                  onClick={() => handleSell(seedType)}
                  className="px-2.5 py-1.5 rounded-lg bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white text-[11px] font-medium transition-all active:scale-95 flex items-center gap-1 whitespace-nowrap"
                >卖出 +{sellValue}<Coins size={12} /></button>
              </div>
            </div>
          );
        })}
      </div>

      {totalWarehouseValue === 0 && (
        <div className="text-center py-8 text-slate-500">
          <Package size={32} className="mx-auto mb-2 opacity-40" />
          <p className="text-sm">仓库是空的</p>
          <p className="text-xs mt-1 text-slate-600">种植并收获果实后会出现在这里</p>
        </div>
      )}
    </div>
  );
}

export function TabBar({ ui }: { ui: FarmUIState }) {
  const { activeTab, setActiveTab } = ui;
  return (
    <div className="flex gap-1 mb-4 bg-slate-800/50 rounded-xl p-1">
      {TABS.map(({ key, label, icon: Icon }) => (
        <button
          key={key}
          onClick={() => setActiveTab(key)}
          className={`flex-1 py-2 rounded-lg text-xs font-medium transition-all flex items-center justify-center gap-1 ${
            activeTab === key
              ? "bg-emerald-500/30 text-emerald-300"
              : "text-slate-400 hover:text-slate-300"
          }`}
        >
          <Icon size={14} />{label}
        </button>
      ))}
    </div>
  );
}

export function QuizButton({ ui }: { ui: FarmUIState }) {
  const { setShowQuiz } = ui;
  return (
    <button
      onClick={() => setShowQuiz(true)}
      className="w-full py-2.5 mb-4 bg-gradient-to-r from-violet-500/20 to-purple-500/20 hover:from-violet-500/30 hover:to-purple-500/30 border border-violet-500/30 text-violet-300 font-medium rounded-xl transition-all flex items-center justify-center gap-2 text-sm"
    >
      <Brain size={16} />学习答题赚阳光 ☀️
    </button>
  );
}

export function DebugButtons({ ui }: { ui: FarmUIState }) {
  const { debugAddSunlight, showMsg } = ui;
  return (
    <div className="flex items-center justify-center gap-2 mb-3">
      <button
        onClick={() => { debugAddSunlight(50); showMsg("+50 阳光", "success"); }}
        className="px-2.5 py-1 bg-yellow-600/70 hover:bg-yellow-500/70 text-white text-[10px] rounded-full border border-yellow-400/40 transition-all hover:scale-105 active:scale-95"
      >+50 阳光</button>
      <button
        onClick={() => { debugAddSunlight(100); showMsg("+100 阳光", "success"); }}
        className="px-2.5 py-1 bg-amber-600/70 hover:bg-amber-500/70 text-white text-[10px] rounded-full border border-amber-400/40 transition-all hover:scale-105 active:scale-95"
      >+100 阳光</button>
    </div>
  );
}

export function FieldTab({ ui, gridWidth }: { ui: FarmUIState; gridWidth?: string }) {
  return (
    <div className="space-y-4">
      <SeedInventory ui={ui} />
      <FieldArea ui={ui} gridWidth={gridWidth} />
      <ToolBar ui={ui} />
    </div>
  );
}

export function ShopTab({ ui }: { ui: FarmUIState }) {
  return <ShopList ui={ui} />;
}

export function WarehouseTab({ ui, showDeliveryEntry }: { ui: FarmUIState; showDeliveryEntry?: boolean }) {
  return <WarehouseList ui={ui} showDeliveryEntry={showDeliveryEntry} />;
}

export function TabContent({ ui, gridWidth, showDeliveryEntry }: {
  ui: FarmUIState; gridWidth?: string; showDeliveryEntry?: boolean;
}) {
  const { activeTab } = ui;
  return (
    <>
      {activeTab === "field" && <FieldTab ui={ui} gridWidth={gridWidth} />}
      {activeTab === "shop" && <ShopTab ui={ui} />}
      {activeTab === "warehouse" && <WarehouseTab ui={ui} showDeliveryEntry={showDeliveryEntry} />}
    </>
  );
}
