import { useState, useEffect } from "react";
import { Settings, Volume2, Music, VolumeX, Music3, Play, SkipBack, SkipForward, Repeat, Shuffle, Volume, Speaker, Copy, Check, Save, Keyboard, Type, Gift, Loader2 } from "lucide-react";
import { audioManager, BgmPlayMode, ClearSfxType, CLEAR_SFX_OPTIONS } from "@/utils/audioManager";
import { getUserInfo, updateNickname } from "@/utils/userInfo";
import { copyToClipboard } from "@/lib/utils";
import { redeemCode } from "@/utils/redeemApi";
import { useGameStore } from "@/store/useGameStore";
import { showToast } from "@/utils/toast";
import type { SpellingInputMode } from "@/types/game";

interface SettingsModalProps {
  open: boolean;
  onClose: () => void;
}

export default function SettingsModal({ open, onClose }: SettingsModalProps) {
  const [sfxOn, setSfxOn] = useState(() => {
    return localStorage.getItem("block_game_sfx") !== "off";
  });
  const [bgmOn, setBgmOn] = useState(() => {
    return localStorage.getItem("block_game_bgm") !== "off";
  });
  const [bgmFiles, setBgmFiles] = useState<string[]>([]);
  const [currentBgmIndex, setCurrentBgmIndex] = useState(0);
  const [bgmPlayMode, setBgmPlayMode] = useState<BgmPlayMode>("loop");
  const [clearSfxType, setClearSfxType] = useState<ClearSfxType>("classic");
  const [bgmVolume, setBgmVolume] = useState(() => audioManager.getBgmVolume());
  const [sfxVolume, setSfxVolume] = useState(() => audioManager.getSfxVolume());
  const [wordPronOn, setWordPronOn] = useState(() => audioManager.isWordPronunciationEnabled());
  const [wordPronRate, setWordPronRate] = useState(() => audioManager.getWordPronunciationRate());
  const [wordPronAccent, setWordPronAccent] = useState<"us" | "uk">(() => audioManager.getWordPronunciationAccent());
  const [userInfo, setUserInfo] = useState(() => getUserInfo());
  const [nickname, setNickname] = useState(userInfo.nickname);
  const [copied, setCopied] = useState(false);
  const [nicknameSaved, setNicknameSaved] = useState(false);
  const [spellingInputMode, setSpellingInputMode] = useState<SpellingInputMode>(() => {
    return (localStorage.getItem("block_game_spelling_input") as SpellingInputMode) || "letters";
  });
  const [redeemInput, setRedeemInput] = useState("");
  const [redeeming, setRedeeming] = useState(false);

  const addCoins = useGameStore((s) => s.addCoins);
  const jumpToLevel = useGameStore((s) => s.jumpToLevel);

  useEffect(() => {
    if (!open) return;
    setSfxOn(audioManager.isSfxEnabled());
    setBgmOn(audioManager.isBgmEnabled());
    setBgmPlayMode(audioManager.getBgmPlayMode());
    setClearSfxType(audioManager.getClearSfxType());
    setBgmVolume(audioManager.getBgmVolume());
    setSfxVolume(audioManager.getSfxVolume());
    setWordPronOn(audioManager.isWordPronunciationEnabled());
    setWordPronRate(audioManager.getWordPronunciationRate());
    setWordPronAccent(audioManager.getWordPronunciationAccent());

    audioManager.loadAllBgmFiles();
    setBgmFiles(audioManager.getBgmFiles());
    setCurrentBgmIndex(audioManager.getCurrentBgmIndex());

    const info = getUserInfo();
    setUserInfo(info);
    setNickname(info.nickname);
    setSpellingInputMode(
      (localStorage.getItem("block_game_spelling_input") as SpellingInputMode) || "letters"
    );
  }, [open]);

  const toggleSfx = () => {
    const next = !sfxOn;
    setSfxOn(next);
    audioManager.setSfxEnabled(next);
  };

  const toggleBgm = () => {
    const next = !bgmOn;
    setBgmOn(next);
    audioManager.setBgmEnabled(next);
  };

  const toggleWordPron = () => {
    const next = !wordPronOn;
    setWordPronOn(next);
    audioManager.setWordPronunciationEnabled(next);
  };

  const handleWordPronRateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = parseFloat(e.target.value);
    setWordPronRate(v);
    audioManager.setWordPronunciationRate(v);
  };

  const changeWordPronAccent = (accent: "us" | "uk") => {
    setWordPronAccent(accent);
    audioManager.setWordPronunciationAccent(accent);
  };

  const testWordPron = () => {
    audioManager.speakWord("apple");
  };

  const changeBgm = (index: number) => {
    setCurrentBgmIndex(index);
    audioManager.changeBgm(index);
  };

  const changePlayMode = (mode: BgmPlayMode) => {
    setBgmPlayMode(mode);
    audioManager.setBgmPlayMode(mode);
  };

  const changeClearSfx = (type: ClearSfxType) => {
    setClearSfxType(type);
    audioManager.setClearSfxType(type);
    audioManager.playClearSfx();
  };

  const handleBgmVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = parseFloat(e.target.value);
    setBgmVolume(v);
    audioManager.setBgmVolume(v);
  };

  const handleSfxVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = parseFloat(e.target.value);
    setSfxVolume(v);
    audioManager.setSfxVolume(v);
  };

  const handleNicknameChange = () => {
    const updated = updateNickname(nickname);
    setUserInfo(updated);
    setNicknameSaved(true);
    setTimeout(() => setNicknameSaved(false), 1500);
  };

  const changeSpellingInputMode = (mode: SpellingInputMode) => {
    setSpellingInputMode(mode);
    localStorage.setItem("block_game_spelling_input", mode);
  };

  const handleCopyUUID = async () => {
    try {
      const success = await copyToClipboard(userInfo.uuid);

      if (success) {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }
    } catch (e) {
      console.error("复制 UUID 失败", e);
    }
  };

  const handleRedeem = async () => {
    if (redeeming) return;
    const code = redeemInput.trim();
    if (!code) {
      showToast("请输入口令", "error");
      return;
    }
    setRedeeming(true);
    try {
      const result = await redeemCode(code);
      if (result.success) {
        const targetLevel = result.reward.targetLevel;
        const coins = result.reward.coins;
        if (coins > 0) {
          addCoins(coins);
        }
        if (targetLevel > 0) {
          jumpToLevel(targetLevel);
        }
        const rewardText = [
          targetLevel > 0 ? `直达第 ${targetLevel} 关` : "",
          coins > 0 ? `${coins} 积分` : "",
        ]
          .filter(Boolean)
          .join("、");
        showToast(`兑换成功：${rewardText}`, "success");
        setRedeemInput("");
      } else {
        const failMsg = (result as { success: false; message: string }).message;
        showToast(failMsg, "error");
      }
    } catch (e) {
      console.error("兑换失败", e);
      showToast("兑换失败，请稍后再试", "error");
    } finally {
      setRedeeming(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-sky-500/30 rounded-3xl p-6 sm:p-8 max-w-sm w-full shadow-2xl flex flex-col max-h-[85vh]">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-sky-400 to-blue-500 flex items-center justify-center shadow-lg shadow-sky-500/50">
            <Settings className="text-white" size={24} />
          </div>
        </div>

        <h2 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-sky-400 via-blue-400 to-cyan-400 mb-6 mt-4 text-center shrink-0">
          游戏设置
        </h2>

        <div className="flex flex-col gap-4 overflow-y-auto min-h-0 flex-1">
          {/* 用户信息 */}
          <div className="bg-gradient-to-br from-violet-900/40 to-purple-900/40 rounded-2xl px-5 py-4 border border-violet-500/30">
            {/* 昵称 */}
            <div className="mb-3">
              <p className="text-slate-400 text-xs mb-1.5">玩家昵称</p>
              <div className="flex items-center gap-2">
                <input
                  type="text"
                  value={nickname}
                  onChange={(e) => setNickname(e.target.value)}
                  placeholder="匿名玩家"
                  maxLength={20}
                  className="flex-1 bg-slate-900/50 rounded-lg px-3 py-2 border border-slate-700/30 text-slate-200 text-sm focus:outline-none focus:border-violet-500/50 transition-all"
                />
                <button
                  onClick={handleNicknameChange}
                  className="p-2 rounded-lg bg-violet-500/20 hover:bg-violet-500/30 border border-violet-500/30 transition-all shrink-0"
                  title="保存昵称"
                >
                  {nicknameSaved ? (
                    <Check size={16} className="text-emerald-400" />
                  ) : (
                    <Save size={16} className="text-violet-300" />
                  )}
                </button>
              </div>
            </div>
            {/* UUID */}
            <div>
              <p className="text-slate-400 text-xs mb-1.5">唯一标识</p>
              <div className="flex items-center gap-2">
                <input
                  type="text"
                  value={userInfo.uuid}
                  disabled
                  className="flex-1 bg-slate-900/50 rounded-lg px-3 py-2 border border-slate-700/30 text-slate-300 text-sm font-mono focus:outline-none transition-all"
                />
                <button
                  onClick={handleCopyUUID}
                  className="p-2 rounded-lg bg-violet-500/20 hover:bg-violet-500/30 border border-violet-500/30 transition-all shrink-0"
                  title="复制 UUID"
                >
                  {copied ? <Check size={16} className="text-emerald-400" /> : <Copy size={16} className="text-violet-300" />}
                </button>
              </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-amber-900/30 to-orange-900/30 rounded-2xl px-5 py-4 border border-amber-500/30">
            <div className="flex items-center gap-2 mb-2">
              <Gift size={16} className="text-amber-300" />
              <p className="text-slate-200 font-medium text-sm">口令兑换</p>
            </div>
            <p className="text-slate-500 text-xs mb-3">输入口令可领取积分或直达关卡，每个口令仅可使用一次。</p>
            <div className="flex items-center gap-2">
              <input
                type="text"
                value={redeemInput}
                onChange={(e) => setRedeemInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    handleRedeem();
                  }
                }}
                placeholder="请输入口令"
                maxLength={32}
                disabled={redeeming}
                className="flex-1 bg-slate-900/50 rounded-lg px-3 py-2 border border-slate-700/30 text-slate-200 text-sm font-mono uppercase tracking-wider focus:outline-none focus:border-amber-500/50 transition-all disabled:opacity-50"
              />
              <button
                onClick={handleRedeem}
                disabled={redeeming || !redeemInput.trim()}
                className="px-4 py-2 rounded-lg bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-bold transition-all flex items-center gap-1.5 shrink-0"
              >
                {redeeming ? <Loader2 size={14} className="animate-spin" /> : null}
                {redeeming ? "兑换中" : "兑换"}
              </button>
            </div>
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${sfxOn ? "bg-amber-500/30" : "bg-slate-700/50"}`}>
                  {sfxOn ? <Volume2 size={20} className="text-amber-300" /> : <VolumeX size={20} className="text-slate-500" />}
                </div>
                <div>
                  <p className="text-slate-200 font-medium">音效</p>
                  <p className="text-slate-500 text-xs">消除、获胜、失败音效</p>
                </div>
              </div>
              <button
                onClick={toggleSfx}
                className={`relative w-14 h-7 rounded-full transition-all ${sfxOn ? "bg-amber-500" : "bg-slate-600"
                  }`}
              >
                <div
                  className={`absolute top-0.5 w-6 h-6 rounded-full bg-white shadow transition-all ${sfxOn ? "left-7" : "left-0.5"
                    }`}
                />
              </button>
            </div>
            {sfxOn && (
              <div className="mt-3 flex items-center gap-3">
                <Speaker size={16} className="text-amber-400 shrink-0" />
                <input
                  type="range"
                  min="0"
                  max="1"
                  step="0.05"
                  value={sfxVolume}
                  onChange={handleSfxVolumeChange}
                  className="flex-1 h-1.5 bg-slate-700/50 rounded-full appearance-none cursor-pointer accent-amber-500"
                />
                <span className="text-amber-300 text-xs font-medium w-8 text-right">{Math.round(sfxVolume * 100)}%</span>
              </div>
            )}
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${bgmOn ? "bg-sky-500/30" : "bg-slate-700/50"}`}>
                  {bgmOn ? <Music size={20} className="text-sky-300" /> : <Music3 size={20} className="text-slate-500" />}
                </div>
                <div>
                  <p className="text-slate-200 font-medium">背景音乐</p>
                  <p className="text-slate-500 text-xs">关卡背景音乐</p>
                </div>
              </div>
              <button
                onClick={toggleBgm}
                className={`relative w-14 h-7 rounded-full transition-all ${bgmOn ? "bg-sky-500" : "bg-slate-600"
                  }`}
              >
                <div
                  className={`absolute top-0.5 w-6 h-6 rounded-full bg-white shadow transition-all ${bgmOn ? "left-7" : "left-0.5"
                    }`}
                />
              </button>
            </div>
            {bgmOn && (
              <div className="mt-3 flex items-center gap-3">
                <Speaker size={16} className="text-sky-400 shrink-0" />
                <input
                  type="range"
                  min="0"
                  max="1"
                  step="0.05"
                  value={bgmVolume}
                  onChange={handleBgmVolumeChange}
                  className="flex-1 h-1.5 bg-slate-700/50 rounded-full appearance-none cursor-pointer accent-sky-500"
                />
                <span className="text-sky-300 text-xs font-medium w-8 text-right">{Math.round(bgmVolume * 100)}%</span>
              </div>
            )}
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${wordPronOn ? "bg-emerald-500/30" : "bg-slate-700/50"}`}>
                  {wordPronOn ? <Volume2 size={20} className="text-emerald-300" /> : <VolumeX size={20} className="text-slate-500" />}
                </div>
                <div>
                  <p className="text-slate-200 font-medium">单词发音</p>
                  <p className="text-slate-500 text-xs">答题时自动朗读单词</p>
                </div>
              </div>
              <button
                onClick={toggleWordPron}
                className={`relative w-14 h-7 rounded-full transition-all ${wordPronOn ? "bg-emerald-500" : "bg-slate-600"}`}
              >
                <div
                  className={`absolute top-0.5 w-6 h-6 rounded-full bg-white shadow transition-all ${wordPronOn ? "left-7" : "left-0.5"}`}
                />
              </button>
            </div>
            {wordPronOn && (
              <div className="mt-3 space-y-3">
                <div>
                  <p className="text-slate-400 text-xs mb-2">发音口音</p>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      onClick={() => changeWordPronAccent("us")}
                      className={`py-2 rounded-xl text-sm font-medium transition-all ${wordPronAccent === "us"
                          ? "bg-emerald-500/30 text-emerald-300 border border-emerald-500/50"
                          : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                        }`}
                    >
                      🇺🇸 美式
                    </button>
                    <button
                      onClick={() => changeWordPronAccent("uk")}
                      className={`py-2 rounded-xl text-sm font-medium transition-all ${wordPronAccent === "uk"
                          ? "bg-emerald-500/30 text-emerald-300 border border-emerald-500/50"
                          : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                        }`}
                    >
                      🇬🇧 英式
                    </button>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <Speaker size={16} className="text-emerald-400 shrink-0" />
                  <input
                    type="range"
                    min="0.5"
                    max="1.5"
                    step="0.05"
                    value={wordPronRate}
                    onChange={handleWordPronRateChange}
                    className="flex-1 h-1.5 bg-slate-700/50 rounded-full appearance-none cursor-pointer accent-emerald-500"
                  />
                  <span className="text-emerald-300 text-xs font-medium w-10 text-right">{wordPronRate.toFixed(2)}x</span>
                </div>
                <button
                  onClick={testWordPron}
                  className="w-full py-2 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-300 rounded-lg border border-emerald-500/30 transition-all text-sm flex items-center justify-center gap-2"
                >
                  <Play size={14} />
                  试听发音 (apple)
                </button>
              </div>
            )}
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-xl bg-violet-500/30 flex items-center justify-center">
                <Keyboard size={20} className="text-violet-300" />
              </div>
              <div>
                <p className="text-slate-200 font-medium">拼写题输入方式</p>
                <p className="text-slate-500 text-xs">答题时拼写单词的输入方法</p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => changeSpellingInputMode("letters")}
                className={`py-3 rounded-xl text-sm font-medium transition-all flex flex-col items-center gap-1 ${spellingInputMode === "letters"
                    ? "bg-violet-500/30 text-violet-300 border border-violet-500/50"
                    : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                  }`}
              >
                <Type size={18} />
                选择字母
              </button>
              <button
                onClick={() => changeSpellingInputMode("keyboard")}
                className={`py-3 rounded-xl text-sm font-medium transition-all flex flex-col items-center gap-1 ${spellingInputMode === "keyboard"
                    ? "bg-violet-500/30 text-violet-300 border border-violet-500/50"
                    : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                  }`}
              >
                <Keyboard size={18} />
                键盘输入
              </button>
            </div>
          </div>

          {bgmOn && bgmFiles.length > 0 && (
            <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
              <div className="flex items-center justify-between mb-3">
                <p className="text-slate-200 font-medium">选择背景音乐</p>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => changeBgm(currentBgmIndex - 1)}
                    disabled={currentBgmIndex <= 0}
                    className="p-2 rounded-lg bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                  >
                    <SkipBack size={18} className="text-slate-300" />
                  </button>
                  <button
                    onClick={() => changeBgm(currentBgmIndex + 1)}
                    disabled={currentBgmIndex >= bgmFiles.length - 1}
                    className="p-2 rounded-lg bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                  >
                    <SkipForward size={18} className="text-slate-300" />
                  </button>
                </div>
              </div>
              <div className="flex flex-col items-center gap-2 bg-slate-900/50 rounded-xl px-4 py-3">
                <div className="flex items-center gap-2">
                  <Music3 size={16} className="text-sky-400" />
                  <span className="text-sky-300 font-medium">
                    {currentBgmIndex + 1} / {bgmFiles.length}
                  </span>
                </div>
                <p className="text-slate-400 text-xs text-center truncate max-w-full">
                  {bgmFiles[currentBgmIndex]?.replace(/\.[^/.]+$/, "")}
                </p>
              </div>

              <div className="mt-3">
                <p className="text-slate-400 text-xs mb-2">播放模式</p>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    onClick={() => changePlayMode("loop")}
                    className={`flex items-center justify-center gap-2 py-2 rounded-xl text-sm font-medium transition-all ${bgmPlayMode === "loop"
                        ? "bg-sky-500/30 text-sky-300 border border-sky-500/50"
                        : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                      }`}
                  >
                    <Repeat size={14} />
                    单曲循环
                  </button>
                  <button
                    onClick={() => changePlayMode("random")}
                    className={`flex items-center justify-center gap-2 py-2 rounded-xl text-sm font-medium transition-all ${bgmPlayMode === "random"
                        ? "bg-sky-500/30 text-sky-300 border border-sky-500/50"
                        : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                      }`}
                  >
                    <Shuffle size={14} />
                    随机播放
                  </button>
                </div>
              </div>
            </div>
          )}

          {sfxOn && (
            <div className="bg-slate-800/50 rounded-2xl px-5 py-4 border border-slate-700/50">
              <div className="flex items-center gap-3 mb-3">
                <div className="w-10 h-10 rounded-xl bg-amber-500/30 flex items-center justify-center">
                  <Volume size={20} className="text-amber-300" />
                </div>
                <div>
                  <p className="text-slate-200 font-medium">消除音效</p>
                  <p className="text-slate-500 text-xs">点击可试听</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {CLEAR_SFX_OPTIONS.map((option) => (
                  <button
                    key={option.value}
                    onClick={() => changeClearSfx(option.value)}
                    className={`py-2 rounded-xl text-sm font-medium transition-all ${clearSfxType === option.value
                        ? "bg-amber-500/30 text-amber-300 border border-amber-500/50"
                        : "bg-slate-700/30 text-slate-400 border border-slate-600/30 hover:bg-slate-700/50"
                      }`}
                  >
                    {option.label}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <button
          onClick={onClose}
          className="w-full mt-6 py-3 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50 shrink-0"
        >
          关闭
        </button>
      </div>
    </div>
  );
}